package me.majhrs16.suite.api.sync;

import java.time.Instant;
import java.util.Objects;

/**
 * One append-only audit entry for a sync action.
 *
 * <p>The record never carries argument values: {@link #argsHash()} is the
 * SHA-256 of the canonical argument digest, with secret parameters replaced by
 * a fixed marker before hashing. {@link #detail()} carries a diagnostic
 * generated by the bus or the handler, never raw arguments.</p>
 *
 * @param timestamp      instant of the attempt
 * @param program        SHA-256 of the program image, or {@code "-"} for official callers
 * @param actor          principal identity ({@code module:<id>} or {@code program:<sha>})
 * @param backend        backend namespace
 * @param action         local action id
 * @param argsHash       lowercase SHA-256 of the redacted argument digest
 * @param status         canonical status name ({@code OK}, {@code DENIED}, ...)
 * @param durationMillis execution time in milliseconds
 * @param detail         diagnostic text without argument values; may be empty
 */
public record ActionAuditRecord(
        Instant timestamp,
        String program,
        String actor,
        String backend,
        String action,
        String argsHash,
        String status,
        long durationMillis,
        String detail
) {

    /** Marker used when the caller is not a third-party program. */
    public static final String NO_PROGRAM = "-";

    /** Marker used when the arguments cannot be digested. */
    public static final String NO_ARGS = "-";

    public ActionAuditRecord {
        Objects.requireNonNull(timestamp, "timestamp");
        program = program == null || program.isBlank() ? NO_PROGRAM : program;
        actor = requireText(actor, "actor");
        backend = requireText(backend, "backend");
        action = requireText(action, "action");
        argsHash = argsHash == null || argsHash.isBlank() ? NO_ARGS : argsHash;
        status = requireText(status, "status");
        if (durationMillis < 0) {
            throw new IllegalArgumentException("durationMillis must not be negative");
        }
        detail = detail == null ? "" : detail;
    }

    private static String requireText(String value, String name) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(name + " must not be blank");
        }
        return value;
    }
}
